//! Golden tests for the cutscene/object/holding/ending actions and Link/Banjo, generated by
//! `GEN_RUST_FIXTURES=1 npx vitest run tests/rustFixtures.cutscene.gen.test.ts`.
//! Each frame flagged in `cmp` must match the TypeScript bit-for-bit.
use jumpman_sim::collision::*;
use jumpman_sim::mario_runtime::*;
use jumpman_sim::state::*;
use serde_json::Value;
use std::sync::Arc;

fn load(path: &str) -> Value {
    serde_json::from_slice(&std::fs::read(format!("{}/{path}", env!("CARGO_MANIFEST_DIR"))).unwrap()).unwrap()
}
fn nums(v: &Value) -> Vec<f64> { v.as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect() }

fn world(id: &str) -> CollisionWorld {
    let data = load(&format!("../../assets/courses/{id}.json"));
    let verts: Vec<[f64; 3]> = data["vertices"].as_array().unwrap().iter().map(|v| { let v = nums(v); [v[0], v[1], v[2]] }).collect();
    let mut w = CollisionWorld::default();
    for t in data["triangles"].as_array().unwrap() {
        let t = nums(t);
        let kind = t[3] as i32;
        let opts = SurfaceOptions { kind, force: t[4] as i32, flags: if (0x76..=0x79).contains(&kind) { 2 } else { 0 }, ..Default::default() };
        w.add_triangle(verts[t[0] as usize], verts[t[1] as usize], verts[t[2] as usize], &opts);
    }
    w
}

/// Returns (frames compared, first mismatching frame with got/want).
fn run(name: &str) -> (usize, Option<(usize, Vec<f64>, Vec<f64>)>) {
    let f = load("tests/fixtures/cutscene_chars_bob.json");
    let sc = &f[name];
    let data = load("../../assets/courses/bob.json");
    let sp = nums(&data["spawn"]["pos"]);
    let spawn = SpawnPoint { action: None, pos: [sp[0], sp[1], sp[2]], face_yaw: data["spawn"]["faceYaw"].as_f64().unwrap() };
    let mut m = MarioRuntime::new(Arc::new(world("bob")), spawn, -1600.0);
    let init = &sc["init"];
    m.set_action(init["action"].as_u64().unwrap() as u32, init["arg"].as_f64().unwrap());
    m.pos[1] += init["dy"].as_f64().unwrap();
    m.forward_vel = init["fv"].as_f64().unwrap();
    if let Some(s) = init.get("sign") { let s = nums(s); m.sign_motion = [s[0], s[1], s[2]]; }
    let kind = sc["kind"].as_str().unwrap();
    let mut compared = 0;
    for (i, row) in sc["script"].as_array().unwrap().iter().enumerate() {
        let r = row.as_array().unwrap();
        let c = ControllerSnapshot {
            focus_yaw: r[5].as_f64(),
            stick_x: r[0].as_f64().unwrap(), stick_y: r[1].as_f64().unwrap(), stick_mag: r[2].as_f64().unwrap(),
            button_down: r[3].as_f64().unwrap() as u32, button_pressed: r[4].as_f64().unwrap() as u32,
        };
        m.step(&c, 0.0, kind == "link", kind == "banjo");
        if !sc["cmp"][i].as_bool().unwrap() { continue; }
        let want = nums(&sc["frames"][i]);
        let got = vec![
            m.pos[0], m.pos[1], m.pos[2], m.vel[0], m.vel[1], m.vel[2], m.face_angle[0], m.face_angle[1], m.face_angle[2],
            m.action as f64, m.forward_vel, m.health, m.action_arg, m.action_state, m.action_timer, m.flags as f64,
        ];
        compared += 1;
        if got != want { return (compared, Some((i, got, want))); }
    }
    (compared, None)
}

fn check(name: &str, min_frames: usize) {
    let (n, bad) = run(name);
    if let Some((i, got, want)) = bad { panic!("{name}: frame {i} differs\n got  {got:?}\n want {want:?}"); }
    assert!(n >= min_frames, "{name}: only {n} frames compared (expected >= {min_frames})");
}

